// src/App.js
import { useEffect, useState } from "react";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend
} from "chart.js";

import {
  fetchLoggedUser,
  fetchPRStatus,
  fetchUserRepos,
  fetchCommits
} from "./api/githubApi";

import MonthYearPicker from "./components/MonthYearPicker";
import { uploadFile } from "./api/githubApi";

const [selectedFile, setSelectedFile] = useState(null);
const [uploadMessage, setUploadMessage] = useState("Upload file from dashboard");

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

function App() {
  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");

  const [labels, setLabels] = useState([]);
  const [counts, setCounts] = useState([]);
  const [total, setTotal] = useState(0);
  const [openPRs, setOpenPRs] = useState(0);
  const [closedPRs, setClosedPRs] = useState(0);
  const [mergedPRs, setMergedPRs] = useState(0);

  const [commitLabels, setCommitLabels] = useState([]);
  const [commitCounts, setCommitCounts] = useState([]);
  const [totalCommits, setTotalCommits] = useState(0);

  const [userCreatedAt, setUserCreatedAt] = useState(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  // ✅ Save token
  useEffect(() => {
    const query = new URLSearchParams(window.location.search);
    const token = query.get("token");
    if (token) {
      localStorage.setItem("token", token);
      window.history.replaceState({}, document.title, "/");
    }
  }, []);

  // ✅ Load user + repos
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    fetchLoggedUser().then(res => {
      setOwner(res.data.login);
      setUserCreatedAt(res.data.created_at);
    });

    fetchUserRepos().then(res => {
      setRepos(res.data);
      if (res.data.length > 0) setSelectedRepo(res.data[0].name);
    });
  }, []);

  // ✅ MASTER BACKEND CALL (PRS + COMMITS)
  const callBackend = async (payload) => {
    // PR DATA
    const prRes = await fetchPRStatus(payload);

    setLabels(prRes.data.labels || []);
    setCounts(prRes.data.counts || []);
    setTotal(prRes.data.total || 0);
    setOpenPRs(prRes.data.open || 0);
    setClosedPRs(prRes.data.closed || 0);
    setMergedPRs(prRes.data.merged || 0);

    // COMMIT DATA
    const commitRes = await fetchCommits(payload);

    const commitMap = {};
    commitRes.data.forEach(commit => {
      const date = commit.commit.committer.date.substring(0, 10);
      commitMap[date] = (commitMap[date] || 0) + 1;
    });

    const sortedDates = Object.keys(commitMap).sort();
    const sortedCounts = sortedDates.map(d => commitMap[d]);

    setCommitLabels(sortedDates);
    setCommitCounts(sortedCounts);
    setTotalCommits(sortedCounts.reduce((a, b) => a + b, 0));
  };

  // ✅ Today Button
  const fetchToday = async () => {
    if (!owner || !selectedRepo) return alert("Missing owner or repo");

    const today = new Date().toISOString().slice(0, 10);

    await callBackend({
      owner,
      repo: selectedRepo,
      startDate: today,
      endDate: today
    });
  };

  // ✅ Analyze Button
  const fetchData = async () => {
    if (!owner || !selectedRepo) return alert("Missing owner or repo");
    if (!startDate || !endDate) return alert("Select month + year");

    await callBackend({
      owner,
      repo: selectedRepo,
      startDate,
      endDate
    });
  };

  const prData = {
    labels,
    datasets: [
      { label: "Pull Requests", data: counts, backgroundColor: "#4F46E5" }
    ]
  };

  const commitData = {
    labels: commitLabels,
    datasets: [
      { label: "Commits", data: commitCounts, backgroundColor: "#16A34A" }
    ]
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>GitHub Analytics Dashboard</h1>

      {!owner && (
        <button
          onClick={() => window.location.href = "http://localhost:8080/auth/github"}
          style={styles.loginBtn}
        >
          Login with GitHub
        </button>
      )}

      {owner && <h3>Logged in as: {owner}</h3>}

      {owner && (
        <>
          <div style={styles.form}>
            <select value={selectedRepo} onChange={e => setSelectedRepo(e.target.value)}>
              {repos.map(repo => (
                <option key={repo.id} value={repo.name}>{repo.name}</option>
              ))}
            </select>

            <MonthYearPicker
              userCreatedAt={userCreatedAt}
              onChange={({ startDate, endDate }) => {
                setStartDate(startDate);
                setEndDate(endDate);
              }}
            />

            <button onClick={fetchData}>Analyze</button>
            <button onClick={fetchToday}>Today</button>
          </div>

          {total > 0 && (
            <div style={styles.cardGrid}>
              <div style={styles.statCard}>Total PRs: {total}</div>
              <div style={{ ...styles.statCard, background: "#DCFCE7" }}>Open: {openPRs}</div>
              <div style={{ ...styles.statCard, background: "#FEF9C3" }}>Closed: {closedPRs}</div>
              <div style={{ ...styles.statCard, background: "#DBEAFE" }}>Merged: {mergedPRs}</div>
            </div>
          )}

          {labels.length > 0 && (
            <div style={{ width: "90%", maxWidth: 950, marginTop: 30 }}>
              <Bar data={prData} />
            </div>
          )}

          {commitLabels.length > 0 && (
            <div style={{ width: "90%", maxWidth: 950, marginTop: 40 }}>
              <h3>Commit Activity</h3>
              <Bar data={commitData} />
              <p>Total Commits: {totalCommits}</p>
            </div>
          )}
        </>
      )}
    </div>
  );
}

const styles = {
  container: { textAlign: "center", padding: 30, fontFamily: "Arial", minHeight: "100vh" },
  heading: { color: "#1E293B" },
  form: { display: "flex", gap: 10, justifyContent: "center", marginBottom: 30, flexWrap: "wrap" },
  loginBtn: { padding: "10px 20px", borderRadius: 6, background: "#111827", color: "white" },
  cardGrid: { display: "flex", gap: 12, justifyContent: "center", marginTop: 20 },
  statCard: { padding: "10px 18px", borderRadius: 10, background: "#E5E7EB" }
};

export default App;
